import { readFile } from "node:fs/promises";
import { join } from "node:path";

import { Args, Flags } from "@oclif/core";
import { describe, expect, it } from "vitest";

import { COMMANDS } from "../../../../src/index";
import { BaseCommand } from "../../../../src/lib/oclif/base";
import { CommandGroups } from "../../../../src/lib/oclif/groups";
import { cliReference } from "../../../../src/lib/oclif/reference";

const packageRoot = join(import.meta.dirname, "../../../..");

/**
 * The marker every generated file of the repo carries in its header
 * (`scripts/generated-outputs.mjs`), which JSON holds as a leading `$comment`.
 */
const marker =
  "generated by apps/cli/tests/unit/lib/oclif/reference.test.ts from the COMMANDS table. DO NOT EDIT: " +
  "rerun it with `corepack pnpm --dir apps/cli exec vitest run tests/unit/lib/oclif/reference.test.ts --update`. " +
  "The docs site renders it as its CLI reference (apps/docs/lib/cli-reference.ts).";

class Fake extends BaseCommand {
  async run(): Promise<never> {
    throw new Error("unused");
  }
}

/** A command the root help lists under the project commands. */
function aCommand(statics: Record<string, unknown> = {}): typeof Fake {
  return Object.assign(class extends Fake {}, {
    description: "Do the thing.",
    group: CommandGroups.project,
    ...statics,
  });
}

describe("command-reference.json", () => {
  // The docs build reads the committed file, so a command change that leaves
  // it behind fails here rather than on the docs site.
  it("is the reference of the COMMANDS table", async () => {
    const manifest = JSON.parse(await readFile(join(packageRoot, "package.json"), "utf8")) as {
      oclif: { bin: string };
    };
    const reference = { $comment: marker, ...cliReference(COMMANDS, manifest.oclif.bin) };

    await expect(`${JSON.stringify(reference, null, 2)}\n`).toMatchFileSnapshot(
      join(packageRoot, "command-reference.json"),
    );
  });
});

describe("cliReference", () => {
  it("orders the commands as the root help does: by group, then groupOrder, then id", () => {
    const reference = cliReference(
      {
        zebra: aCommand(),
        start: aCommand({ group: CommandGroups.localServer }),
        claim: aCommand({ groupOrder: 2 }),
        setup: aCommand({ groupOrder: 1 }),
      },
      "zitadel",
    );

    expect(reference.groups).toEqual(Object.values(CommandGroups));
    expect(reference.commands.map(({ id, group }) => [id, group])).toEqual([
      ["setup", CommandGroups.project],
      ["claim", CommandGroups.project],
      ["zebra", CommandGroups.project],
      ["start", CommandGroups.localServer],
    ]);
  });

  it("names a command as it is typed and its aliases the same way", () => {
    const reference = cliReference(
      { "auth-method:sso:enable": aCommand({ aliases: ["sso:on"] }) },
      "zitadel",
    );

    expect(reference.commands[0]).toMatchObject({
      id: "auth-method sso enable",
      aliases: ["sso on"],
    });
  });

  it("lists --json and BaseCommand's flags once, as the global flags", () => {
    const reference = cliReference(
      { setup: aCommand({ flags: { force: Flags.boolean({ description: "Overwrite." }) } }) },
      "zitadel",
    );

    expect(reference.globalFlags.map((flag) => flag.name)).toEqual([
      "json",
      ...Object.keys(BaseCommand.baseFlags),
    ]);
    expect(reference.globalFlags[0]).toEqual({
      name: "json",
      description: "Format output as json.",
      type: "boolean",
    });
    expect(reference.commands[0]?.flags.map((flag) => flag.name)).toEqual(["force"]);
  });

  it("lists the flags a family adds to the base flags after the command's own", () => {
    const reference = cliReference(
      {
        "auth-method:sso:enable": aCommand({
          baseFlags: { ...BaseCommand.baseFlags, schema: Flags.string({ description: "Schema." }) },
          flags: { provider: Flags.string({ description: "Provider." }) },
        }),
      },
      "zitadel",
    );

    expect(reference.commands[0]?.flags.map((flag) => flag.name)).toEqual(["provider", "schema"]);
  });

  it("keeps what the help says of a flag, and only what differs from the defaults", () => {
    const reference = cliReference(
      {
        list: aCommand({
          flags: {
            force: Flags.boolean({ char: "f", description: "Overwrite." }),
            open: Flags.boolean({ default: true, allowNo: true, description: "Open it." }),
            limit: Flags.integer({ min: 1, max: 100, description: "Page size." }),
            tail: Flags.integer({ default: 200, description: "Lines." }),
            framework: Flags.string({
              options: ["next", "nuxt"],
              required: true,
              helpGroup: "REQUIRED FIELD",
              description: "Framework.",
            }),
            filter: Flags.string({ multiple: true, exclusive: ["all"], summary: "Filter." }),
            design: Flags.string({ hidden: true }),
          },
        }),
      },
      "zitadel",
    );

    expect(reference.commands[0]?.flags).toEqual([
      { name: "force", char: "f", description: "Overwrite.", type: "boolean" },
      { name: "open", description: "Open it.", type: "boolean", allowNo: true, default: true },
      { name: "limit", description: "Page size.", type: "option", min: 1, max: 100 },
      { name: "tail", description: "Lines.", type: "option", default: 200 },
      {
        name: "framework",
        description: "Framework.",
        type: "option",
        required: true,
        options: ["next", "nuxt"],
        helpGroup: "REQUIRED FIELD",
      },
      {
        name: "filter",
        description: "Filter.",
        type: "option",
        multiple: true,
        exclusive: ["all"],
      },
    ]);
  });

  it("keeps the arguments the help shows", () => {
    const reference = cliReference(
      {
        get: aCommand({
          args: {
            id: Args.string({ description: "The id.", required: true }),
            format: Args.string({ options: ["json", "yaml"] }),
            secret: Args.string({ hidden: true }),
          },
        }),
      },
      "zitadel",
    );

    expect(reference.commands[0]?.args).toEqual([
      { name: "id", description: "The id.", required: true },
      { name: "format", options: ["json", "yaml"] },
    ]);
  });

  it("keeps an example's command line after the bin, and renders the help's templates", () => {
    const reference = cliReference(
      {
        setup: aCommand({
          summary: "Set up <%= command.id %>.",
          description: "Run `<%= config.bin %> start` first.",
          examples: [
            "<%= config.bin %> setup --framework next",
            { command: "<%= config.bin %> setup --json", description: "For an agent." },
          ],
        }),
      },
      "zitadel",
    );

    expect(reference.commands[0]).toMatchObject({
      description: "Set up setup.\n\nRun `zitadel start` first.",
      examples: [
        { command: "setup --framework next" },
        { command: "setup --json", description: "For an agent." },
      ],
    });
  });

  it("leaves hidden commands out", () => {
    const reference = cliReference(
      { setup: aCommand(), design: aCommand({ hidden: true }) },
      "zitadel",
    );

    expect(reference.commands.map(({ id }) => id)).toEqual(["setup"]);
  });

  it.each([
    [
      "an example that does not start with the bin",
      { examples: ["setup --json"] },
      /does not start/,
    ],
    ["a template it does not render", { description: "Run <%= config.dirname %>." }, /renders/],
    ["a command without a group", { group: undefined }, /declares no group/],
    ["a command without help text", { description: undefined }, /neither a summary/],
    [
      "a command with flags of its own instead of the global ones",
      { baseFlags: {} },
      /global flags/,
    ],
  ])("refuses %s", (_case, statics, message) => {
    expect(() => cliReference({ setup: aCommand(statics) }, "zitadel")).toThrow(message);
  });
});
